    def savings_key(i, j):
        ri, rj = routes[i], routes[j]
        if not ri or not rj:
            return -10**18
        la, lb = route_load(ri), route_load(rj)
        if la + lb > capacity:
            return -10**18
        base = route_cost(ri) + route_cost(rj)

        def eval_merge(x, y):
            if route_load(x) + route_load(y) > capacity:
                return None
            merged = x + y
            newc = route_cost(merged)
            return base - newc

        candidates = []
        candidates.append(eval_merge(ri, rj))
        candidates.append(eval_merge(ri, list(reversed(rj))))
        candidates.append(eval_merge(list(reversed(ri)), rj))
        candidates.append(eval_merge(list(reversed(ri)), list(reversed(rj))))
        best = -10**18
        for v in candidates:
            if v is not None and v > best:
                best = v
        return best

    def merge_phase():
        nonlocal routes
        for _ in range(5):
            if len(routes) <= max(1, int(hint)):
                break
            if len(routes) <= 1:
                break
            best_i, best_j, best_merged, best_gain = None, None, None, 0
            m = len(routes)
            for i in range(m):
                if len(routes) <= max(1, int(hint)):
                    break
                for j in range(m):
                    if i == j:
                        continue
                    if route_load(routes[i]) + route_load(routes[j]) > capacity:
                        continue
                    gain = savings_key(i, j)
                    if gain <= 0:
                        continue
                    merged = attempt_merge(routes[i], routes[j])
                    if merged is None:
                        continue
                    if gain > best_gain or (gain == best_gain and (i, j) < (best_i, best_j)):
                        best_i, best_j, best_merged, best_gain = i, j, merged, gain
            if best_merged is None:
                break
            i, j = best_i, best_j
            if i > j:
                routes.pop(i)
                routes.pop(j)
            else:
                routes.pop(j)
                routes.pop(i)
            routes.append(best_merged)

    merge_phase()

    # 3) Intra-route 2-opt (kept)
    def two_opt_intra(r):
        n = len(r)
        if n < 4:
            return r
        iters = 0
        while iters < 12:
            iters += 1
            improved = False
            base = route_cost(r)
            for i in range(n - 1):
                for k in range(i + 2, n):
                    newr = r[:i] + list(reversed(r[i:k + 1])) + r[k + 1:]
                    if route_cost(newr) + 1e-9 < base:
                        r = newr
                        n = len(r)
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                break
        return r

    for idx in range(len(routes)):
        routes[idx] = two_opt_intra(routes[idx])

    # 4) Inter-route relocate (kept)
    def relocate_phase():
        nonlocal routes
        for _ in range(4):
            improved_any = False
            loads = [route_load(r) for r in routes]
            costs = [route_cost(r) for r in routes]
            m = len(routes)
            for i in range(m):
                if i >= len(routes):
                    break
                ri = routes[i]
                if len(ri) <= 1:
                    continue
                for pos in range(len(ri)):
                    cust = ri[pos]
                    best = None  # (delta, j, new_ri, new_rj, ins_dummy)
                    for j in range(m):
                        if j == i or j >= len(routes):
                            continue
                        if loads[j] + demands[cust] > capacity:
                            continue
                        rj = routes[j]
                        new_ri = ri[:pos] + ri[pos + 1:]
                        base = costs[i] + costs[j]
                        # evaluate insertion positions deterministically; prune with best-first threshold
                        for ins in range(len(rj) + 1):
                            if ins == 0:
                                new_rj = [cust] + rj
                            elif ins == len(rj):
                                new_rj = rj + [cust]
                            else:
                                new_rj = rj[:ins] + [cust] + rj[ins:]
                            new_cost = route_cost(new_ri) + route_cost(new_rj)
                            delta = base - new_cost
                            if delta > 1e-9:
                                if best is None or delta > best[0]:
                                    best = (delta, j, new_ri, new_rj)
                    if best is not None:
                        _, j, new_ri, new_rj = best
                        routes[i] = new_ri
                        routes[j] = new_rj
                        loads[i] -= demands[cust]
                        loads[j] += demands[cust]
                        costs[i] = route_cost(new_ri)
                        costs[j] = route_cost(new_rj)
                        improved_any = True
                        if not routes[i]:
                            routes.pop(i)
                        break
                if improved_any:
                    break
            if not improved_any:
                break

    relocate_phase()

    routes = [r for r in routes if r]
    return routes
